// Generates the traceable GL / AP / AR 2.0 document set in docs/gl-ap-ar/ from docs/gl-ap-ar/source/*.mjs and from the code itself, and validates the mapping.
//   npx tsx scripts/build-gl-docs.mjs [--check]
// Generated (do not edit): 01 BRD, 02 SRS, 07 sprint log, 08 traceability matrix, annex A data dictionary, B API reference, C permissions.
// Hand-written documents live next to them (03 solution design, 04 technical design, 05 test strategy, 06 user manual, annexes D..H).
import fs from 'node:fs';
import path from 'node:path';
import { getTableConfig } from 'drizzle-orm/pg-core';
import * as schema from '../src/db/schema.ts';
import { PERMISSION_MODULES } from '../src/permissionSchema.ts';
import { AREAS, BRS, OUT_OF_SCOPE } from '../docs/gl-ap-ar/source/brd.mjs';
import { SRS } from '../docs/gl-ap-ar/source/srs.mjs';
import { SPRINTS } from '../docs/gl-ap-ar/source/sprints.mjs';
import { CASES } from '../docs/test-cases/catalogue-source.mjs';

const OUT = 'docs/gl-ap-ar'; const CHECK = process.argv.includes('--check');
const problems = [];
const today = '2026-10-15';

// ---------- expand and validate ----------
const caseIds = new Set(CASES.map(c => c.id));
const expand = (s) => { const m = s.match(/^([A-Z0-9]+)-(\d+)\.\.([A-Z0-9]+)-(\d+)$/); if (!m) return [s]; const out = []; for (let i = Number(m[2]); i <= Number(m[4]); i++) out.push(`${m[1]}-${String(i).padStart(3, '0')}`); return out; };
const brById = new Map(BRS.map(b => [b.id, b]));
const frs = []; // {id, br, statement, where, tests[]}
for (const b of BRS) {
  const s = SRS[b.id];
  if (!s) { problems.push(`${b.id}: no SRS entry`); continue; }
  const tests = [...new Set(s.tests.flatMap(expand))];
  for (const t of tests) if (!caseIds.has(t)) problems.push(`${b.id}: unknown test case ${t}`);
  if (b.status !== 'Planned' && tests.length === 0) problems.push(`${b.id}: ${b.status} requirement without a test case`);
  s.fr.forEach((f, i) => frs.push({ id: `${b.id.replace('BR-', 'FR-')}.${i + 1}`, br: b.id, statement: f[0], where: f[1], tests }));
}
for (const k of Object.keys(SRS)) if (!brById.has(k)) problems.push(`SRS refers to unknown ${k}`);
const sprintsOfBr = new Map(BRS.map(b => [b.id, []]));
for (const sp of SPRINTS) for (const it of sp.items) for (const b of it[1]) { if (!brById.has(b)) problems.push(`Sprint ${sp.n}: unknown ${b}`); else sprintsOfBr.get(b).push(sp.n); }
for (const b of BRS) if (!sprintsOfBr.get(b.id).length) problems.push(`${b.id}: not in any sprint`);
for (const b of BRS) if (b.status === 'Built' && !sprintsOfBr.get(b.id).some(n => SPRINTS.find(s => s.n === n).status === 'Done')) problems.push(`${b.id}: Built but no Done sprint`);
const frOfCase = new Map();
for (const f of frs) for (const t of f.tests) (frOfCase.get(t) || frOfCase.set(t, []).get(t)).push(f.id);
const unmapped = CASES.filter(c => !frOfCase.has(c.id));
if (problems.length) { console.error('Problems:\n  ' + problems.join('\n  ')); process.exit(1); }
const stat = (s) => BRS.filter(b => b.status === s).length;
if (CHECK) { console.log(`OK: ${BRS.length} BRs, ${frs.length} FRs, ${SPRINTS.length} sprints, ${CASES.length - unmapped.length}/${CASES.length} test cases traced.`); process.exit(0); }

const w = (f, s) => { fs.mkdirSync(path.dirname(path.join(OUT, f)), { recursive: true }); fs.writeFileSync(path.join(OUT, f), s.trimEnd() + '\n'); };
const tbl = (head, rows) => `| ${head.join(' | ')} |\n|${head.map(() => '---').join('|')}|\n${rows.map(r => `| ${r.map(c => String(c ?? '').replace(/\|/g, '\\|').replace(/\n/g, ' ')).join(' | ')} |`).join('\n')}`;
const sprintLabel = (n) => `S${n}`;
const GEN = `> Generated by \`scripts/build-gl-docs.mjs\` from \`docs/gl-ap-ar/source\`. Do not edit; change the source and rebuild.`;

// ---------- 01 BRD ----------
w('01-business-requirements-document.md', `# Business Requirements Document — General Ledger, Accounts Receivable, Accounts Payable 2.0

${GEN}

| | |
|---|---|
| Product | Warraq ERP 2.0 — finance core (General Ledger, Receivables, Payables, Bank) |
| Version / date | 1.0 / ${today} |
| Status | Baseline for the delivered scope (Sprints 0–9); planned scope in Sprints 11–20 |
| Source documents | \`docs/reference/Finance-Core-Blueprint.pdf\` (v0.1), owner decisions recorded in \`docs/archive/gl-step1-plan.md\`, \`docs/design-notes/gl-step1-5-decisions.md\`, \`docs/design-notes/ar-ap-bank-design.md\`, \`docs/design-notes/date-fields-standard.md\`, \`docs/design-notes/posting-control.md\` |
| Related | SRS (02), Solution design (03), Technical design (04), Test strategy (05), User manual (06), Sprint log (07), Traceability (08) |

## 1. Purpose

Replace document-derived bookkeeping with a real double-entry ledger that sales, purchasing, inventory and (later) payroll all settle into, so that accounts receivable, accounts payable, bank, tax and every financial statement are queries over the same posted lines. This document states, once and traceably, **what the business needs**; the SRS states what the system shall do about it.

## 2. Business context and problem

Before 2.0 the system computed every report from documents (invoices, expenses, bills, vouchers). That is correct for a single entity but gives accountants no chart of accounts of their own, no manual adjustments, no analytical dimensions, no subledger tied to a control account, no multi-document receipts, no bank reconciliation and no period control beyond month close. Tier-1 ERP practice (SAP, Oracle, Dynamics) treats all of these as basics.

## 3. Objectives

1. One ledger, one posting engine, one report engine: no figure is calculated in two places.
2. The accountant can see, adjust, analyse and close the books without developer help.
3. Receivables and payables behave as subledgers: every party balance ties to its control account to the cent.
4. Money movements (receipts, payments, bank charges) are controlled, auditable and reconcilable to the bank.
5. Nothing can be posted outside the period rules, and every override is attributable.
6. The solution serves thousands of concurrent users across many companies, safely isolated.

## 4. Scope

**In scope:** ${BRS.length} business requirements in ${AREAS.length} areas (section 6). ${stat('Built')} are built, ${stat('Partial')} partly built, ${stat('Planned')} planned.

**Out of scope (this programme):**
${OUT_OF_SCOPE.map(o => `* ${o.text} (${o.ref}) — ${o.why}`).join('\n')}

## 5. Stakeholders and users

| Role | Interest |
|---|---|
| Owner / CFO | Reliable statements, period control, approval safeguards, audit |
| Accountant (preparer) | Chart, journals, reconciliation, receipts and payments |
| Approver / Finance manager | Approves journals, reopens reconciliations, overrides locks |
| AR / AP clerk | Receipts, payments, aging, statements |
| Branch manager | Branch-limited views |
| Auditor | Read access, audit trail, immutable postings |
| Administrator | Roles, permissions, company setup |
| Developer / support | Documentation, tests, release safety |

## 6. Business requirements register

Status: Built = delivered in Demo 2.0; Partial = delivered in part (gap named); Planned = in scope, not built. Priority: MoSCoW. "Blueprint" = Finance Core Blueprint requirement ids. Sprints are listed in the sprint log (07).

${AREAS.map(a => `### ${a.id} — ${a.name}\n\n${BRS.filter(b => b.area === a.id).map(b => `**${b.id} ${b.title}** — ${b.priority}, ${b.status}${b.bp.length ? `, Blueprint ${b.bp.join(', ')}` : ''}, source ${b.source}, sprint ${sprintsOfBr.get(b.id).map(sprintLabel).join(', ')}.\n${b.text}`).join('\n\n')}`).join('\n\n')}

## 7. Constraints and assumptions

* Single company currency (SAR); multi-currency and intercompany are out of scope.
* Live (1.0) is changed by fixes only; all development is on the 2.0 track and reaches Live only by an explicit promotion (BR-NFR-06).
* Existing document-based reports remain the figures of record until the cut-over (BR-RPT-12).
* ZATCA e-invoicing code is not altered by this programme.
* Document dates, posting guard and permission model are platform standards that every later feature must follow.

## 8. Success criteria

* Ledger-vs-Documents agrees to the cent for every company; the consistency check shows no error-level failure.
* Every built requirement has automated test coverage traced in the matrix (08).
* A new company can complete the user-manual flow (06) without developer help.

## 9. Blueprint coverage

${tbl(['Blueprint requirement', 'Business requirement(s)'], (() => { const m = new Map(); for (const b of BRS) for (const f of b.bp) (m.get(f) || m.set(f, []).get(f)).push(b.id); return [...m.entries()].sort().map(([f, bs]) => [f, bs.join(', ')]); })())}
`);

// ---------- 02 SRS ----------
w('02-software-requirements-specification.md', `# Software Requirements Specification — General Ledger, Receivables, Payables 2.0

${GEN}

Version 1.0 / ${today}. Satisfies the BRD (01). Each system requirement (FR) states what the system shall do, where it is implemented, and which test cases prove it (case ids resolve in \`docs/test-cases/\`).

## 1. System overview

A multi-tenant web application (React client, Node/Express API, PostgreSQL with row-level security). Documents (invoices, expenses, bills, vouchers, settlements) and manual journals post through one engine, \`postJournalEntry\`, into \`journal_entries\` / \`journal_lines\`. Subledgers, aging, statements and every report are queries over those lines. See the solution design (03).

## 2. Cross-cutting requirements

| Id | Requirement |
|---|---|
| SYS-01 | Every request shall run in one database transaction scoped to \`req.targetCompanyId\`; any error rolls the whole request back. |
| SYS-02 | No route shall accept a client-supplied company id; every client-supplied foreign key shall be checked to belong to the company. |
| SYS-03 | Every dated posting shall pass \`assertPostingAllowed\`. |
| SYS-04 | Posted ledger lines shall never be updated or deleted; correction is by reversal. |
| SYS-05 | Every new table shall carry company_id, composite (company_id, id) keys where referenced, RLS, and an index on company_id. |
| SYS-06 | Every new user-visible string shall have English, Arabic and Urdu text. |
| SYS-07 | Money shall be stored as decimal(14,2) and computed with 2-decimal rounding (round2). |

## 3. Functional requirements

${AREAS.map(a => `### ${a.id} — ${a.name}\n\n${tbl(['FR', 'BR', 'The system shall', 'Implemented in', 'Test cases'], frs.filter(f => brById.get(f.br).area === a.id).map(f => [f.id, f.br, f.statement, f.where, f.tests.length ? f.tests.join(', ') : '(target: sprint ' + sprintsOfBr.get(f.br).join(',') + ')']))}`).join('\n\n')}

## 4. Interfaces

* HTTP/JSON API: see annex B (generated from the route files).
* Permissions: annex C. Data model: annex A.
* Files: Excel (chart, reports, aging, ledger), CSV (bank statement import).
* Print: browser print through \`DocumentRenderer\` (A4, right-to-left for Arabic/Urdu).

## 5. Non-functional requirements

${tbl(['Id', 'Requirement', 'Measure'], [['NFR-01', 'Concurrency', '2000 virtual users: p95 ≤ 800 ms reads, ≤ 1500 ms postings, no 5xx (case NFR-009)'], ['NFR-02', 'Report speed', 'Trial balance and general ledger on 100 000 lines ≤ 5 s (RPT-022, NFR-006)'], ['NFR-03', 'Integrity', 'Consistency check: zero error-level failures after any activity'], ['NFR-04', 'Security', 'RLS on every table; permission matrix enforced server-side'], ['NFR-05', 'Auditability', 'Elevated actions audited with user, company, time'], ['NFR-06', 'Recoverability', 'Release by script with backup, reviewed schema plan, rollback'], ['NFR-07', 'Localisation', 'EN/AR/UR, RTL parity'], ['NFR-08', 'Testability', 'Real-database automated tests for every behaviour']])}
`);

// ---------- 07 sprint log ----------
w('07-sprint-log.md', `# Sprint log and plan — GL / AR / AP 2.0

${GEN}

Sprints are numbered. Done sprints list the commits that delivered them (git, branch \`v2\`); planned sprints list the BRD items they will deliver. Forward mapping (BR → sprint) and back mapping (sprint item → BR) are both here and in the traceability matrix (08). The first ten sprints were delivered in one continuous build, 2026-10-14 → 2026-10-15.

${tbl(['Sprint', 'Name', 'Status', 'Dates', 'Goal'], SPRINTS.map(s => [`S${s.n}`, s.name, s.status, s.dates, s.goal]))}

${SPRINTS.map(s => `## Sprint ${s.n} — ${s.name} (${s.status})\n\n${s.goal}${s.commits.length ? `\n\nCommits: ${s.commits.map(c => '`' + c + '`').join(', ')}` : ''}\n\n${tbl(['Item', 'Title', 'Business requirements', 'System requirements'], s.items.map((it, i) => [`S${s.n}-${String(i + 1).padStart(2, '0')}`, it[0], it[1].map(b => `${b} ${brById.get(b).title}`).join('; '), it[1].flatMap(b => frs.filter(f => f.br === b).map(f => f.id)).join(', ')]))}`).join('\n\n')}

## Forward mapping: requirement → sprint

${tbl(['BR', 'Title', 'Status', 'Sprints'], BRS.map(b => [b.id, b.title, b.status, sprintsOfBr.get(b.id).map(sprintLabel).join(', ')]))}

## Roadmap (not yet built)

${tbl(['Sprint', 'Name', 'Delivers'], SPRINTS.filter(s => s.status === 'Planned').map(s => [`S${s.n}`, s.name, s.items.map(i => i[1].join(', ')).join('; ')]))}
`);

// ---------- 08 traceability ----------
w('08-traceability-matrix.md', `# Traceability matrix — GL / AR / AP 2.0

${GEN}

Coverage: ${BRS.length} business requirements → ${frs.length} system requirements → ${CASES.length - unmapped.length} of ${CASES.length} test cases traced → ${SPRINTS.length} sprints.${unmapped.length ? ` ${unmapped.length} cases are not tied to a requirement (listed in section 3).` : ' Every test case is tied to a requirement.'}

## 1. Forward: business requirement → system requirements → test cases → sprints

${tbl(['BR', 'Title', 'Status', 'FRs', 'Test cases', 'Sprints'], BRS.map(b => { const f = frs.filter(x => x.br === b.id); const t = [...new Set(f.flatMap(x => x.tests))]; return [b.id, b.title, b.status, f.map(x => x.id).join(', '), t.length ? `${t.length}: ${t.slice(0, 6).join(', ')}${t.length > 6 ? ' …' : ''}` : '—', sprintsOfBr.get(b.id).map(sprintLabel).join(', ')]; }))}

## 2. Backward: test case → system requirement → business requirement

${tbl(['Case', 'Title', 'Automation', 'FR', 'BR'], CASES.map(c => { const f = frOfCase.get(c.id) || []; return [c.id, c.title, c.automation.startsWith('tests/') ? c.automation : c.automation, f.join(', '), [...new Set(f.map(x => frs.find(y => y.id === x).br))].join(', ')]; }))}

## 3. Test cases not tied to a requirement

${unmapped.length ? unmapped.map(c => `* ${c.id} ${c.title}`).join('\n') : 'None.'}

## 4. Sprint → business requirement

${tbl(['Sprint', 'Item', 'Business requirements'], SPRINTS.flatMap(s => s.items.map((it, i) => [`S${s.n} ${s.name}`, `S${s.n}-${String(i + 1).padStart(2, '0')} ${it[0]}`, it[1].join(', ')])))}

## 5. Blueprint requirement → business requirement

${tbl(['Blueprint', 'BR', 'Status'], BRS.flatMap(b => b.bp.map(f => [f, b.id, b.status])).sort((a, b) => a[0].localeCompare(b[0])))}
`);

// ---------- Annex A: data dictionary ----------
const comments = new Map(); // table -> col -> comment ; table -> description
{
  const src = fs.readFileSync('src/db/schema.ts', 'utf8').replace(/\r\n/g, '\n').split('\n'); let cur = null; let pending = [];
  for (const l of src) {
    const t = l.match(/^export const \w+ = pgTable\('([^']+)'/);
    if (t) { cur = t[1]; comments.set(cur, { desc: pending.join(' ').replace(/^\/\/\s?/, '').replace(/ \/\/ ?/g, ' '), cols: new Map() }); pending = []; continue; }
    if (/^\/\//.test(l)) { pending.push(l); continue; }
    if (!l.trim()) { pending = []; }
    if (cur) { const c = l.match(/^\s+\w+: \w+\('([^']+)'.*?\/\/\s*(.+)$/); if (c) comments.get(cur).cols.set(c[1], c[2].trim()); }
    if (/^}\)\)/.test(l)) cur = null;
  }
}
const IN_SCOPE = ['company_accounts', 'system_accounts', 'journal_entries', 'journal_lines', 'manual_journals', 'manual_journal_lines', 'manual_journal_events', 'posting_policies', 'payment_allocations', 'vouchers', 'bank_reconciliations', 'bank_statement_lines', 'bank_accounts', 'customers', 'vendors', 'invoices', 'expenses', 'purchase_bills', 'fiscal_months', 'dimension_types', 'dimension_values', 'dimension_combinations', 'dimension_combination_entries', 'cost_centers', 'account_dimension_rules', 'report_definitions', 'report_rows', 'report_row_selectors', 'report_columns', 'audit_logs'];
const tables = new Map();
for (const v of Object.values(schema)) { try { const c = getTableConfig(v); tables.set(c.name, c); } catch { /* not a table */ } }
let dd = `# Annex A — Data dictionary (GL / AR / AP tables)\n\n${GEN}\n\nColumn comments are taken from \`src/db/schema.ts\`. Every table has row-level security on \`company_id\` (or its parent). Business dates follow \`docs/design-notes/date-fields-standard.md\`.\n`;
for (const name of IN_SCOPE) {
  const c = tables.get(name); if (!c) { dd += `\n## ${name}\n\n(not found)\n`; continue; }
  const meta = comments.get(name);
  dd += `\n## ${name}\n\n${meta?.desc ? meta.desc + '\n\n' : ''}${tbl(['Column', 'Type', 'Null', 'Default', 'Note'], c.columns.map(col => [col.name, col.getSQLType(), col.notNull ? 'no' : 'yes', col.hasDefault ? 'yes' : '', meta?.cols.get(col.name) || '']))}\n`;
  const ix = [...c.indexes.map(i => `index ${i.config.name}`), ...c.uniqueConstraints.map(u => `unique ${u.name}`), ...c.foreignKeys.map(f => `fk ${f.getName()}`), ...c.checks.map(k => `check ${k.name}`)];
  if (ix.length) dd += `\nKeys and constraints: ${ix.join('; ')}\n`;
}
w('annex-a-data-dictionary.md', dd);

// ---------- Annex B: API ----------
const server = fs.readFileSync('server.ts', 'utf8');
const imports = new Map([...server.matchAll(/import (\w+) from '\.\/server\/routes\/([\w]+)\.js'/g)].map(m => [m[1], m[2]]));
const mounts = new Map(); for (const m of server.matchAll(/app\.use\('([^']+)'(?:, \w+)*, (\w+)\)/g)) if (imports.has(m[2])) mounts.set(imports.get(m[2]), m[1]);
const APIFILES = ['ledgerAccounts', 'ledgerJournals', 'ledgerOpening', 'ledgerDimensions', 'ledgerReports', 'ledgerPostingPolicy', 'ledgerSubledger', 'settlements', 'bankReconciliation', 'transactions', 'expenses', 'reports'];
let api = `# Annex B — API reference (GL / AR / AP routes)\n\n${GEN}\n\nParsed from \`server/routes/*.ts\`. "Permission" lists the \`hasPermission\` keys found in the handler. All routes run in the tenant transaction (\`withTenantDb\`) and are scoped to the session company.\n`;
for (const f of APIFILES) {
  const p = `server/routes/${f}.ts`; if (!fs.existsSync(p)) continue; const lines = fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n').split('\n'); const rows = [];
  lines.forEach((l, i) => { const m = l.match(/router\.(get|post|put|patch|delete)\('([^']+)'/); if (m) { const perms = [...new Set([...lines.slice(i, i + 14).join(' ').matchAll(/hasPermission\(req\.user, [`']([\w.${}]+)[`']/g)].map(x => x[1]))]; const gp = l.match(/guarded\('(\w+)'/); rows.push([m[1].toUpperCase(), (mounts.get(f) || '/api') + m[2], gp ? `${f === 'bankReconciliation' ? 'bankReconciliation.' : ''}${gp[1]}` : perms.join(', ')]); } });
  api += `\n## ${f}.ts\n\n${rows.length ? tbl(['Method', 'Path', 'Permission'], rows) : '(none)'}\n`;
}
w('annex-b-api-reference.md', api);

// ---------- Annex C: permissions ----------
const gl = PERMISSION_MODULES.filter(m => ['general_ledger', 'sales', 'procurements', 'financial_config'].includes(m.groupId));
w('annex-c-permissions-matrix.md', `# Annex C — Permission modules (GL / AR / AP)\n\n${GEN}\n\nSource of truth: \`src/permissionSchema.ts\`. A user's rights are the union of all assigned roles; administrators hold every right. Delete means cancel or deactivate, never erase.\n\n${tbl(['Group', 'Module', 'Leaf', 'Meaning'], gl.flatMap(m => m.leaves.map(l => [m.groupId, `${m.id} — ${m.label}`, `${m.id}.${l.key}`, l.label])))}`);

console.log(`Written: BRD (${BRS.length} BR), SRS (${frs.length} FR), sprint log (${SPRINTS.length}), traceability (${CASES.length - unmapped.length}/${CASES.length} cases), annexes A/B/C.`);
